/// The name this revision gives a device property (`INPUT_PROP_*`).
pub const fn property_name(code: u16) -> Option<&'static str> {
    match code {
        0x0 => Some("INPUT_PROP_POINTER"),
        0x1 => Some("INPUT_PROP_DIRECT"),
        0x2 => Some("INPUT_PROP_BUTTONPAD"),
        0x3 => Some("INPUT_PROP_SEMI_MT"),
        0x4 => Some("INPUT_PROP_TOPBUTTONPAD"),
        0x5 => Some("INPUT_PROP_POINTING_STICK"),
        0x6 => Some("INPUT_PROP_ACCELEROMETER"),
        0x7 => Some("INPUT_PROP_PRESSUREPAD"),
        _ => None,
    }
}

/// The name this revision gives a event type (`EV_*`).
pub const fn event_type_name(code: u16) -> Option<&'static str> {
    match code {
        0x0 => Some("EV_SYN"),
        0x1 => Some("EV_KEY"),
        0x2 => Some("EV_REL"),
        0x3 => Some("EV_ABS"),
        0x4 => Some("EV_MSC"),
        0x5 => Some("EV_SW"),
        0x11 => Some("EV_LED"),
        0x12 => Some("EV_SND"),
        0x14 => Some("EV_REP"),
        0x15 => Some("EV_FF"),
        0x16 => Some("EV_PWR"),
        0x17 => Some("EV_FF_STATUS"),
        _ => None,
    }
}

/// The name this revision gives a synchronization code (`SYN_*`).
pub const fn synchronization_name(code: u16) -> Option<&'static str> {
    match code {
        0x0 => Some("SYN_REPORT"),
        0x1 => Some("SYN_CONFIG"),
        0x2 => Some("SYN_MT_REPORT"),
        0x3 => Some("SYN_DROPPED"),
        _ => None,
    }
}

